@dataclass(frozen=True, kw_only=True)
class FingerprintMetrics:
    """Class for holding metrics on a single fingerprint. Note: this is distinct from
    FingerprintingDetailMetrics and FingerprintingSummaryMetrics in that it is calculated on a
    single fingerprint, and attempts to describe how likely that fingerprint is to have arisen
    from an actual sample as opposed to having artifacts such as contamination, or strong bias
    towards homozygous genotypes.
    """

    sample_alias: str = ""
    """The Sample alias taken from RG header or #CHROME line"""

    source: str = ""
    """The originating file (if available) for this fingerprint"""

    info: str = ""
    """Additional information about the fingerprint"""

    haplotypes: int = 0
    """Number of haplotypes examined"""

    haplotypes_with_evidence: int = 0
    """Number of haplotypes that had evidence in the source file"""

    definite_genotypes: int = 0
    """Number of haplotypes that had enough evidence to make a definite genotype call (genotype
    LOD > Threshold
    """

    num_hom_allele1: int = 0
    """Number of major allele homozygous calls"""

    num_hom_allele2: int = 0
    """Number of minor allele homozygous calls"""

    num_hom_any: int = 0
    """Number of homozygous calls of either allele (might not be the sum of NUM_HOM_ALLELE1 and
    NUM_HOM_ALLELE1 due to rounding
    """

    num_het: int = 0
    """Number of heterozygous calls"""

    expected_hom_allele1: float = 0.0
    """Expected number of major allele homozygous calls"""

    expected_hom_allele2: float = 0.0
    """Expected number of major allele homozygous calls"""

    expected_het: float = 0.0
    """Expected number of heterozygous calls"""

    chi_squared_pvalue: float = 0.0
    """The Chi-squared pvalue of the observed counts vector relative to the expected counts, (3x2
    table)
    """

    log10_chi_squared_pvalue: float = 0.0
    """The log10 of the Chi-squared pvalue"""

    cross_entropy_lod: float = 0.0
    """The categorical cross entropy of the counts of genotypes relative to expected (big is bad)"""

    het_chi_squared_pvalue: float = 0.0
    """The Chi-squared pvalue for the number of HETs and HOMs relative to the expected counts
    (2x2 table)
    """

    log10_het_chi_squared_pvalue: float = 0.0
    """The log10 of the Chi-squared pvalue for the number of HETs and HOMs"""

    het_cross_entropy_lod: float = 0.0
    """The categorical cross entropy of the counts of HETs and HOMs relative to the expected
    counts (big is bad)
    """

    hom_chi_squared_pvalue: float = 0.0
    """The Chi-squared pvalue for NUM_HOM_ALLELE1 and NUM_HOM_ALLELE2 relative to the expected
    counts (2x2 table)
    """

    log10_hom_chi_squared_pvalue: float = 0.0
    """The log10 of the Chi-squared pvalue for NUM_HOM_ALLELE1 and NUM_HOM_ALLELE2"""

    hom_cross_entropy_lod: float = 0.0
    """The categorical cross entropy of NUM_HOM_ALLELE1 and NUM_HOM_ALLELE2 relative to the
    expected counts (big is bad)
    """

    lod_self_check: float = 0.0
    """The fingerprinting LOD score this sample gets when compared to itself (big is good)"""

    discriminatory_power: float = 0.0
    """The difference in fingerprinting LOD between LOD_SELF_CHECK and the LOD score found when
    fingerprinting it against a random permutation of the probablity vectors (PLs) in each of the
    haplotypes. (big is good.)
    """


