@dataclass(frozen=True, kw_only=True)
class GcBiasDetailMetrics:
    """Class that holds detailed metrics about reads that fall within windows of a certain GC bin
    on the reference genome.
    """

    accumulation_level: str = ""

    reads_used: ReadsUsed
    """This option is used to mark including or excluding duplicates."""

    gc: int = 0
    """The G+C content of the reference sequence represented by this bin. Values are from 0% to
    100%
    """

    windows: int = 0
    """The number of windows on the reference genome that have this G+C content."""

    read_starts: int = 0
    """The number of reads whose start position is at the start of a window of this GC."""

    mean_base_quality: int = 0
    """The mean quality (determined via the error rate) of all bases of all reads that are
    assigned to windows of this GC.
    """

    normalized_coverage: float = 0.0
    """The ratio of "coverage" in this GC bin vs. the mean coverage of all GC bins. A number of 1
    represents mean coverage, a number less than one represents lower than mean coverage (e.g.
    0.5 means half as much coverage as average) while a number greater than one represents higher
    than mean coverage (e.g. 3.1 means this GC bin has 3.1 times more reads per window than
    average).
    """

    error_bar_width: float = 0.0
    """The radius of error bars in this bin based on the number of observations made. For example
    if the normalized coverage is 0.75 and the error bar width is 0.1 then the error bars would
    be drawn from 0.65 to 0.85.
    """

    sample: str | None = None
    """The sample to which these metrics apply. If null, it means they apply to all reads in the
    file.
    """

    library: str | None = None
    """The library to which these metrics apply. If null, it means that the metrics were
    accumulated at the sample level.
    """

    read_group: str | None = None
    """The read group to which these metrics apply. If null, it means that the metrics were
    accumulated at the library or sample level.
    """


