@dataclass(frozen=True, kw_only=True)
class GenotypeConcordanceDetailMetrics:
    """Class that holds detail metrics about Genotype Concordance."""

    variant_type: VariantType
    """The type of the event (i.e. either SNP or INDEL)"""

    truth_sample: str = ""
    """The name of the 'truth' sample"""

    call_sample: str = ""
    """The name of the 'call' sample"""

    truth_state: TruthState
    """The state of the 'truth' sample (i.e. HOM_REF, HET_REF_VAR1, HET_VAR1_VAR2...)"""

    call_state: CallState
    """The state of the 'call' sample (i.e. HOM_REF, HET_REF_VAR1...)"""

    count: int = 0
    """The number of events of type TRUTH_STATE and CALL_STATE for the EVENT_TYPE and SAMPLEs"""

    contingency_values: str = ""
    """The list of contingency table values (TP, TN, FP, FN) that are deduced from the truth/call
    state comparison, given the reference.

    In general, we are comparing two sets of alleles. Therefore, we can have zero or more
    contingency table values represented in one comparison. For example, if the truthset is a
    heterozygous call with both alleles non-reference (HET_VAR1_VAR2), and the callset is a
    heterozygous call with both alleles non-reference with one of the alternate alleles matching
    an alternate allele in the callset, we would have a true positive, false positive, and false
    negative. The true positive is from the matching alternate alleles, the false positive is the
    alternate allele found in the callset but not found in the truthset, and the false negative
    is the alternate in the truthset not found in the callset.

    We also include a true negative in cases where the reference allele is found in both the
    truthset and callset.
    """


@dataclass(frozen=True, kw_only=True)
class GenotypeConcordanceSummaryMetrics:
    """Class that holds summary metrics about Genotype Concordance."""

    variant_type: VariantType
    """The type of the event (i.e. either SNP or INDEL)"""

    truth_sample: str = ""
    """The name of the 'truth' sample"""

    call_sample: str = ""
    """The name of the 'call' sample"""

    het_sensitivity: float = 0.0
    """The sensitivity for all heterozygous variants (Sensitivity is TP / (TP + FN))"""

    het_ppv: float = 0.0
    """The ppv (positive predictive value) for all heterozygous variants (PPV is the TP / (TP +
    FP))
    """

    het_specificity: float = 0.0
    """The specificity for all heterozygous variants cannot be calculated"""

    homvar_sensitivity: float = 0.0
    """The sensitivity for all homozygous variants (Sensitivity is TP / (TP + FN))"""

    homvar_ppv: float = 0.0
    """The ppv (positive predictive value) for all homozygous variants (PPV is the TP / (TP +
    FP))
    """

    homvar_specificity: float = 0.0
    """The specificity for all homozygous variants cannot be calculated."""

    var_sensitivity: float = 0.0
    """The sensitivity for all (heterozygous and homozygous) variants (Sensitivity is TP / (TP +
    FN))
    """

    var_ppv: float = 0.0
    """The ppv (positive predictive value) for all (heterozygous and homozygous) variants (PPV is
    the TP / (TP + FP))
    """

    var_specificity: float = 0.0
    """The specificity for all (heterozygous and homozygous) variants (Specificity is TN / (FP +
    TN))
    """

    genotype_concordance: float = 0.0
    """The genotype concordance for all possible states. Genotype Concordance is the number of
    times the truth and call states match exactly / all truth and call combinations made
    """

    non_ref_genotype_concordance: float = 0.0
    """The non-ref genotype concordance, ie for all var states only. Non Ref Genotype Concordance
    is the number of times the truth and call states match exactly for *vars only* / all truth
    and call *var* combinations made
    """


@dataclass(frozen=True, kw_only=True)
class HsMetrics:
    """Metrics generated by CollectHsMetrics for the analysis of target-capture sequencing
    experiments. The metrics in this class fall broadly into three categories.
    """

    bait_set: str = ""
    """The name of the bait set used in the hybrid selection."""

    bait_territory: int = 0
    """The number of bases which are localized to one or more baits."""

    bait_design_efficiency: float = 0.0
    """The ratio of TARGET_TERRITORY/BAIT_TERRITORY. A value of 1 indicates a perfect design
    efficiency, while a valud of 0.5 indicates that half of bases within the bait region are not
    within the target region.
    """

    on_bait_bases: int = 0
    """The number of PF_BASES_ALIGNED that are mapped to the baited regions of the genome."""

    near_bait_bases: int = 0
    """The number of PF_BASES_ALIGNED that are mapped to within a fixed interval containing a
    baited region, but not within the baited section per se.
    """

    off_bait_bases: int = 0
    """The number of PF_BASES_ALIGNED that are mapped away from any baited region."""

    pct_selected_bases: float = 0.0
    """The fraction of PF_BASES_ALIGNED located on or near a baited region (ON_BAIT_BASES +
    NEAR_BAIT_BASES)/PF_BASES_ALIGNED.
    """

    pct_off_bait: float = 0.0
    """The fraction of PF_BASES_ALIGNED that are mapped away from any baited region,
    OFF_BAIT_BASES/PF_BASES_ALIGNED.
    """

    on_bait_vs_selected: float = 0.0
    """The fraction of bases on or near baits that are covered by baits,
    ON_BAIT_BASES/(ON_BAIT_BASES + NEAR_BAIT_BASES).
    """

    mean_bait_coverage: float = 0.0
    """The mean coverage of all baits in the experiment."""

    pct_usable_bases_on_bait: float = 0.0
    """The fraction of aligned, on-bait bases out of the PF bases available. (NOTE: This uses
    duplicate reads for both numerator and denominator)
    """

    pct_usable_bases_on_target: float = 0.0
    """The fraction of aligned, de-duped, on-target bases out of all the PF bases available."""

    fold_enrichment: float = 0.0
    """The fold by which the baited region has been amplified above genomic background."""

    hs_library_size: int | None = None
    """The estimated number of unique molecules in the selected part of the library."""

    hs_penalty_10x: float = 0.0
    """The "hybrid selection penalty" incurred to get 80% of target bases to 10X. This metric
    should be interpreted as: if I have a design with 10 megabases of target, and want to get 10X
    coverage I need to sequence until PF_ALIGNED_BASES = 10^7 * 10 * HS_PENALTY_10X.
    """

    hs_penalty_20x: float = 0.0
    """The "hybrid selection penalty" incurred to get 80% of target bases to 20X. This metric
    should be interpreted as: if I have a design with 10 megabases of target, and want to get 20X
    coverage I need to sequence until PF_ALIGNED_BASES = 10^7 * 20 * HS_PENALTY_20X.
    """

    hs_penalty_30x: float = 0.0
    """The "hybrid selection penalty" incurred to get 80% of target bases to 30X. This metric
    should be interpreted as: if I have a design with 10 megabases of target, and want to get 30X
    coverage I need to sequence until PF_ALIGNED_BASES = 10^7 * 30 * HS_PENALTY_30X.
    """

    hs_penalty_40x: float = 0.0
    """The "hybrid selection penalty" incurred to get 80% of target bases to 40X. This metric
    should be interpreted as: if I have a design with 10 megabases of target, and want to get 40X
    coverage I need to sequence until PF_ALIGNED_BASES = 10^7 * 40 * HS_PENALTY_40X.
    """

    hs_penalty_50x: float = 0.0
    """The "hybrid selection penalty" incurred to get 80% of target bases to 50X. This metric
    should be interpreted as: if I have a design with 10 megabases of target, and want to get 50X
    coverage I need to sequence until PF_ALIGNED_BASES = 10^7 * 50 * HS_PENALTY_50X.
    """

    hs_penalty_100x: float = 0.0
    """The "hybrid selection penalty" incurred to get 80% of target bases to 100X. This metric
    should be interpreted as: if I have a design with 10 megabases of target, and want to get
    100X coverage I need to sequence until PF_ALIGNED_BASES = 10^7 * 100 * HS_PENALTY_100X.
    """

    target_territory: int = 0
    """The number of unique bases covered by the intervals of all targets that should be covered"""

    genome_size: int = 0
    """The number of bases in the reference genome used for alignment."""

    total_reads: int = 0
    """The total number of reads in the SAM or BAM file examined."""

    pf_reads: int = 0
    """The number of passing filter reads (PF)."""

    pf_bases: int = 0
    """The number of bases in the PF_READS of a SAM or BAM file"""

    pf_unique_reads: int = 0
    """The number of PF_READS that are not marked as duplicates."""

    pf_uq_reads_aligned: int = 0
    """The number of PF_UNIQUE_READS that are aligned with mapping score > 0 to the reference
    genome.
    """

    pf_bases_aligned: int = 0
    """The number of PF_BASES that are aligned with mapping score > 0 to the reference genome."""

    pf_uq_bases_aligned: int = 0
    """The number of PF unique bases that are aligned with mapping score > 0 to the reference
    genome.
    """

    on_target_bases: int = 0
    """The number of PF aligned bases that mapped to a targeted region of the genome."""

    pct_pf_reads: float = 0.0
    """The fraction of reads passing filter, PF_READS/TOTAL_READS."""

    pct_pf_uq_reads: float = 0.0
    """The fraction of unique reads passing filter, PF_UNIQUE_READS/TOTAL_READS."""

    pct_pf_uq_reads_aligned: float = 0.0
    """The fraction of unique reads passing filter that align to the reference,
    PF_UQ_READS_ALIGNED/PF_UNIQUE_READS.
    """

    mean_target_coverage: float = 0.0
    """The mean coverage of targets."""

    median_target_coverage: float = 0.0
    """The median coverage of targets."""

    max_target_coverage: int = 0
    """The maximum coverage of reads that mapped to target regions of an experiment."""

    min_target_coverage: int = 0
    """The minimum coverage of reads that mapped to target regions of an experiment."""

    zero_cvg_targets_pct: float = 0.0
    """The fraction of targets that did not reach coverage=1 over any base."""

    pct_exc_dupe: float = 0.0
    """The fraction of aligned bases that were filtered out because they were in reads marked as
    duplicates.
    """

    pct_exc_adapter: float = 0.0
    """The fraction of aligned bases in reads that have MQ=0 and whose 5' end consists of adapter
    sequence.
    """

    pct_exc_mapq: float = 0.0
    """The fraction of aligned bases that were filtered out because they were in reads with low
    mapping quality.
    """

    pct_exc_baseq: float = 0.0
    """The fraction of aligned bases that were filtered out because they were of low base
    quality.
    """

    pct_exc_overlap: float = 0.0
    """The fraction of aligned bases that were filtered out because they were the second
    observation from an insert with overlapping reads.
    """

    pct_exc_off_target: float = 0.0
    """The fraction of aligned bases that were filtered out because they did not align over a
    target base.
    """

    fold_80_base_penalty: float = 0.0
    """The fold over-coverage necessary to raise 80% of bases in "non-zero-cvg" targets to the
    mean coverage level in those targets.
    """

    pct_target_bases_1x: float = 0.0
    """The fraction of all target bases achieving 1X or greater coverage."""

    pct_target_bases_2x: float = 0.0
    """The fraction of all target bases achieving 2X or greater coverage."""

    pct_target_bases_10x: float = 0.0
    """The fraction of all target bases achieving 10X or greater coverage."""

    pct_target_bases_20x: float = 0.0
    """The fraction of all target bases achieving 20X or greater coverage."""

    pct_target_bases_30x: float = 0.0
    """The fraction of all target bases achieving 30X or greater coverage."""

    pct_target_bases_40x: float = 0.0
    """The fraction of all target bases achieving 40X or greater coverage."""

    pct_target_bases_50x: float = 0.0
    """The fraction of all target bases achieving 50X or greater coverage."""

    pct_target_bases_100x: float = 0.0
    """The fraction of all target bases achieving 100X or greater coverage."""

    pct_target_bases_250x: float = 0.0
    """The fraction of all target bases achieving 250X or greater coverage."""

    pct_target_bases_500x: float = 0.0
    """The fraction of all target bases achieving 500X or greater coverage."""

    pct_target_bases_1000x: float = 0.0
    """The fraction of all target bases achieving 1000X or greater coverage."""

    pct_target_bases_2500x: float = 0.0
    """The fraction of all target bases achieving 2500X or greater coverage."""

    pct_target_bases_5000x: float = 0.0
    """The fraction of all target bases achieving 5000X or greater coverage."""

    pct_target_bases_10000x: float = 0.0
    """The fraction of all target bases achieving 10000X or greater coverage."""

    pct_target_bases_25000x: float = 0.0
    """The fraction of all target bases achieving 25000X or greater coverage."""

    pct_target_bases_50000x: float = 0.0
    """The fraction of all target bases achieving 50000X or greater coverage."""

    pct_target_bases_100000x: float = 0.0
    """The fraction of all target bases achieving 100000X or greater coverage."""

    at_dropout: float = 0.0
    """A measure of how undercovered <= 50% GC regions are relative to the mean. For each GC bin
    [0..50] we calculate a = % of target territory, and b = % of aligned reads aligned to these
    targets. AT_DROPOUT is then sum(a-b if a-b > 0 else 0). E.g. if the value is 5%, this implies
    that 5% of total reads that should have mapped to GC<=50% regions mapped elsewhere.
    """

    gc_dropout: float = 0.0
    """A measure of how undercovered >= 50% GC regions are relative to the mean. For each GC bin
    [50..100] we calculate a = % of target territory, and b = % of aligned reads aligned to these
    targets. GC_DROPOUT is then sum(a-b if a-b > 0 else 0). E.g. if the value is 5% this implies
    that 5% of total reads that should have mapped to GC>=50% regions mapped elsewhere.
    """

    het_snp_sensitivity: float = 0.0
    """The theoretical HET SNP sensitivity."""

    het_snp_q: float = 0.0
    """The Phred Scaled Q Score of the theoretical HET SNP sensitivity."""

    sample: str | None = None
    """The sample to which these metrics apply. If null, it means they apply to all reads in the
    file.
    """

    library: str | None = None
    """The library to which these metrics apply. If null, it means that the metrics were
    accumulated at the sample level.
    """

    read_group: str | None = None
    """The read group to which these metrics apply. If null, it means that the metrics were
    accumulated at the library or sample level.
    """


